def git_blob_sha(content):
    return hashlib.sha1(b"blob " + str(len(content)).encode() + b"\0" + content).hexdigest()


def apply_update(root, files):
    root = Path(root).expanduser().resolve()
    if not (root/"main.py").is_file() or not (root/"proj_sec").is_dir():
        raise ValueError("Run from the project folder containing main.py and proj_sec.")
    pending = []
    for relative, entry in files.items():
        rel = Path(relative)
        path = root/rel
        if rel.is_absolute() or ".." in rel.parts or not path.resolve().is_relative_to(root):
            raise ValueError(f"Unsafe update path: {relative}")
        desired = entry["updated"].encode("utf-8")
        if path.suffix == ".py":
            compile(entry["updated"], relative, "exec")
        current = path.read_bytes() if path.exists() else None
        if current == desired:
            continue
        expected = entry.get("original_blob")
        if expected and (current is None or git_blob_sha(current) != expected):
            raise ValueError(f"Unexpected source revision: {relative}; no project files changed.")
        pending.append((relative, path, desired))
    if not pending:
        return {"changed": 0, "backup": None}
    stamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ") + "-" + uuid.uuid4().hex[:8]
    backup = root/".cache/model-selected-update-backups"/stamp
    backup.mkdir(parents=True)
    for relative, path, desired in pending:
        if path.exists():
            saved = backup/relative
            saved.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(path, saved)
    for relative, path, desired in pending:
        mode = path.stat().st_mode & 0o777 if path.exists() else 0o644
        path.parent.mkdir(parents=True, exist_ok=True)
        temporary = path.with_name(path.name + ".model-selected.tmp")
        temporary.write_bytes(desired)
        os.chmod(temporary, mode)
        temporary.replace(path)
    (backup/"update-manifest.json").write_text(json.dumps({
        "policy": "guarded-model-omission-review-v2", "version": "0.5.0",
        "updated_files": [relative for relative, _, _ in pending],
    }, indent=2) + "\n")
    return {"changed": len(pending), "backup": str(backup)}


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--project", type=Path, default=Path.cwd())
    args = parser.parse_args(argv)
    files = dict(FILES)
    files["scripts/apply_model_selected_update.py"] = {
        "updated": Path(__file__).read_text(encoding="utf-8"), "original_blob": None,
    }
    result = apply_update(args.project, files)
    print(f"Coverage review update: {result['changed']} file(s) changed.")
    if result["backup"]:
        print("Backups:", result["backup"])
    print("Project version: 0.5.0. Existing results, model responses, caches, and binaries were not regenerated.")
    print("Next: python -m unittest discover -s tests -v")
    print("Then run: caffeinate -i python scripts/run_all_pairs.py --mode run --device mps --dtype bfloat16 --output outputs/coverage-final")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

